  @override
  String get cycleInsightLate =>
      'आपका मासिक धर्म देर से चल रहा है। यह आपके सोचने से अधिक सामान्य है और हमेशा यह नहीं दर्शाता कि कुछ गलत है। तनाव, नींद में बदलाव, बीमारी, अचानक वज़न में बदलाव और कठोर व्यायाम आपके चक्र को कई दिनों या यहां तक कि हफ्तों तक देरी कर सकते हैं। यदि 2 सप्ताह से अधिक हो गए हैं, तो किसी विश्वसनीय वयस्क या डॉक्टर से बात करना उचित है।';

  @override
  String get cycleInsightPeriodSoon =>
      'आपका मासिक धर्म किसी भी दिन आ सकता है। प्रोजेस्टेरोन का स्तर गिर रहा है, जो मासिक धर्म शुरू करने का संकेत है। आप अधिक भावुक, थका हुआ या पीठ के निचले हिस्से में दर्द महसूस कर सकती हैं — ये संकेत हैं कि आपका शरीर तैयार हो रहा है। हर हाल में पास में पैड रखें।';

  @override
  String get cycleInsightPeriod =>
      'आपका मासिक धर्म इसलिए है क्योंकि आपके शरीर को इस महीने बनाई गई गर्भाशय की परत की जरूरत नहीं थी, इसलिए वह उसे बाहर निकाल रहा है। यह एस्ट्रोजन और प्रोजेस्टेरोन में गिरावट के कारण होता है — आपके दो मुख्य चक्र हार्मोन। ऐंठन इसलिए होती है क्योंकि गर्भाशय परत को बाहर निकालने के लिए सिकुड़ रहा है। आराम, हीट पैड और हाइड्रेटेड रहना अभी वास्तव में मदद कर सकता है।';

  @override
  String get cycleInsightFollicular =>
      'अब आपका शरीर अपने अंडाशय में एक अंडा विकसित और परिपक्व कर रहा है। बढ़ता एस्ट्रोजन स्तर बहुत अच्छा काम कर रहा है — आपकी गर्भाशय की परत का पुनर्निर्माण कर रहा है और आपका मूड और ऊर्जा बढ़ा रहा है। अधिकांश लोग इस चरण में अपना सर्वश्रेष्ठ महसूस करते हैं। यह सक्रिय, सामाजिक होने और एकाग्रता वाले कामों के लिए शानदार समय है।';

  @override
  String get cycleInsightOvulation =>
      'आज आपका शरीर एक अंडा छोड़ रहा है। LH नामक हार्मोन में उछाल ने यह शुरू किया है, और आपका एस्ट्रोजन अपने चरम पर है। आप अधिक स्पष्ट और लचीला डिस्चार्ज देख सकती हैं — यह पूरी तरह से सामान्य है और वास्तव में प्रजनन प्रणाली को कार्य करने में मदद करता है। कुछ लोगों को ओव्यूलेशन के दौरान निचले पेट के एक तरफ हल्का दर्द महसूस होता है, जो भी सामान्य है।';

  @override
  String get cycleInsightLuteal =>
      'ओव्यूलेशन के बाद, आपका शरीर संभावित गर्भावस्था की तैयारी के लिए अधिक प्रोजेस्टेरोन का उत्पादन करता है। यह हार्मोन अधिकांश PMS लक्षणों के लिए जिम्मेदार है — सूजन, स्तन कोमलता, मूड स्विंग्स और थकान इस चरण में बहुत आम हैं। यदि आपका मासिक धर्म नहीं आ रहा है, तो ये लक्षण आने से 5 से 7 दिन पहले चरम पर होंगे। आप कल्पना नहीं कर रही हैं, यह हार्मोनल है।';

