      'शोध भारी मासिक रक्तस्राव वाली सभी किशोरियों में, यहाँ तक कि उनके पहले मासिक धर्म के बाद के पहले वर्ष के भीतर भी, एक व्यापक रक्तस्राव मूल्यांकन करने की वकालत करता है। यदि आप 2 घंटे से कम में एक पैड या टैम्पोन भिगो रही हैं, बड़े थक्के निकाल रही हैं, या अपने पीरियड के दौरान चक्कर और थकान महसूस कर रही हैं, तो किसी डॉक्टर से बात करें। प्रभावी उपचार उपलब्ध हैं — जिसमें आयरन पूरकता, हार्मोनल विकल्प और अन्य दवाएँ शामिल हैं — जो जीवन की गुणवत्ता को काफ़ी बेहतर बना सकते हैं।';

